\[
F(w_{t+1})\le F(w_t)-\eta\langle\nabla F(w_t),g_t\rangle
+\frac{L\eta^{2}}{2}\|g_t\|^{2}.
\tag{L1}
\]
\end{lemma}
\begin{proof}
By $L$‑smoothness \eqref{A1'},
\[
F(w_{t+1})\le F(w_t)+\langle\nabla F(w_t),w_{t+1}-w_t\rangle
+\frac{L}{2}\|w_{t+1}-w_t\|^{2}.
\]
